export const PANEL_HTML = "<!doctype html>\n<html lang=\"es\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<meta name=\"theme-color\" content=\"#f2efe9\">\n<title>Taller ASTÉRIA</title>\n<link rel=\"icon\" href=\"__LOGO__\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;1,400&family=Oswald:wght@300;400;500&family=Jost:wght@300;400;500&display=swap\" rel=\"stylesheet\">\n<style>\n/* El taller es la trastienda de la misma tienda: mismo papel, misma tinta, las\n   mismas tres voces tipograficas que asteriamx.pages.dev. Aqui la marca vive en\n   los detalles (numeros, sellos de estado, reglas finas); el trabajo manda. */\n:root{\n  --ink:#050403;--char:#443f3b;--brown:#472d1d;--maroon:#922939;--blue:#2d70ad;\n  --stone:#c8c2ad;--taupe:#6b655e;--paper:#f2efe9;--paper-2:#eae4d9;--paper-3:#e2dacb;--field:#faf8f4;\n  --line:rgba(5,4,3,.14);--line-2:rgba(5,4,3,.08);\n  --font-display:'Cormorant Garamond', Georgia, serif;\n  --font-label:'Oswald', 'Arial Narrow', sans-serif;\n  --font-body:'Jost', system-ui, -apple-system, sans-serif;\n  --ease:cubic-bezier(.16,1,.3,1);\n  --rail:232px;\n}\n*{margin:0;padding:0;box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%}\nbody{font-family:var(--font-body);background:var(--paper);color:var(--ink);line-height:1.55;\n  -webkit-font-smoothing:antialiased;min-height:100vh;min-height:100dvh}\n::selection{background:var(--maroon);color:var(--paper)}\ninput,textarea{caret-color:var(--maroon)}\nimg{display:block;max-width:100%}\nbutton{font:inherit;color:inherit;background:none;border:none;cursor:pointer;-webkit-tap-highlight-color:transparent}\na{color:inherit;text-underline-offset:3px;text-decoration-thickness:1px}\n:focus-visible{outline:1.5px solid var(--maroon);outline-offset:3px}\n[hidden]{display:none!important}\n*{scrollbar-width:thin;scrollbar-color:var(--stone) transparent}\n::-webkit-scrollbar{width:8px;height:8px}::-webkit-scrollbar-thumb{background:var(--stone);border-radius:8px}\n/* Cormorant trae numeros de estilo antiguo: en dinero el \"1\" parece una I. */\n.num{font-variant-numeric:lining-nums tabular-nums;font-feature-settings:\"lnum\" 1,\"tnum\" 1}\n.ico{width:20px;height:20px;flex:none;stroke:currentColor;fill:none;stroke-width:1.4;stroke-linecap:round;stroke-linejoin:round}\n.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}\n\n/* ---------- entrada ---------- */\n.login{min-height:100vh;min-height:100dvh;display:grid;place-items:center;padding:32px 20px;\n  background:radial-gradient(120% 80% at 50% 0%,var(--paper) 40%,var(--paper-2) 100%)}\n.login-box{width:100%;max-width:380px;text-align:center;animation:sube .7s var(--ease) both}\n.login-box img{width:64px;height:64px;margin:0 auto 22px}\n.login h1{font-family:var(--font-display);font-weight:400;font-size:2.8rem;line-height:1;letter-spacing:-.01em}\n.login h1 i{color:var(--maroon)}\n.login p.lead{color:var(--taupe);font-weight:300;margin:12px 0 34px}\n.login form{text-align:left;display:grid;gap:18px}\n.login .err{color:var(--maroon);font-size:.9rem;min-height:1.4em;text-align:center;margin:-4px 0 -6px}\n.pass{position:relative}\n.pass .in{padding-right:48px}\n.pass button{position:absolute;right:4px;top:50%;transform:translateY(-50%);padding:10px;color:var(--taupe)}\n.pass button:hover,.pass button[aria-pressed=\"true\"]{color:var(--ink)}\n\n/* ---------- campos y botones ---------- */\n.campo label,.lbl{display:block;font-family:var(--font-label);text-transform:uppercase;letter-spacing:.16em;font-size:.68rem;color:var(--char);margin-bottom:8px}\n.in{width:100%;padding:13px 14px;border:1px solid var(--line);background:var(--field);font-family:var(--font-body);\n  font-size:1rem;color:var(--ink);border-radius:2px;transition:border-color .2s,box-shadow .2s;appearance:none;-webkit-appearance:none}\n.in::placeholder{color:#8d867d}\n.in:focus{outline:none;border-color:var(--ink);box-shadow:0 0 0 3px rgba(146,41,57,.12)}\ntextarea.in{resize:vertical;min-height:84px;line-height:1.5}\ninput[type=number].in{-moz-appearance:textfield}\ninput[type=number].in::-webkit-inner-spin-button,input[type=number].in::-webkit-outer-spin-button{-webkit-appearance:none;margin:0}\n.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;font-family:var(--font-label);text-transform:uppercase;\n  letter-spacing:.16em;font-size:.74rem;padding:14px 24px;border:1px solid var(--ink);border-radius:2px;\n  transition:background .25s,color .25s,border-color .25s;white-space:nowrap}\n.btn .ico{width:16px;height:16px}\n.btn-ink{background:var(--ink);color:var(--paper)}\n.btn-ink:hover{background:var(--maroon);border-color:var(--maroon)}\n.btn-line:hover{background:var(--ink);color:var(--paper)}\n.btn-quiet{border-color:transparent;color:var(--taupe);padding-inline:12px}\n.btn-quiet:hover{color:var(--maroon)}\n.btn-sm{padding:10px 14px;font-size:.66rem}\n.btn[disabled]{opacity:.45;pointer-events:none}\n.btn.ocupado{position:relative;color:transparent!important;pointer-events:none}\n.btn.ocupado .ico{opacity:0}\n.btn.ocupado::after{content:\"\";position:absolute;width:15px;height:15px;border:1.5px solid var(--paper);border-right-color:transparent;border-radius:50%;animation:gira .7s linear infinite}\n.btn-full{width:100%}\n\n/* ---------- armazon ---------- */\n.app{display:grid;grid-template-columns:var(--rail) minmax(0,1fr);min-height:100vh;min-height:100dvh}\n.rail{position:sticky;top:0;height:100vh;height:100dvh;border-right:1px solid var(--line);display:flex;flex-direction:column;padding:26px 18px 22px}\n.marca{display:flex;align-items:center;gap:12px;padding:0 10px 32px}\n.marca img{width:40px;height:40px}\n.marca b{display:block;font-family:var(--font-display);font-weight:400;font-size:1.45rem;letter-spacing:.08em;line-height:1}\n.marca span{display:block;font-family:var(--font-label);text-transform:uppercase;letter-spacing:.3em;font-size:.58rem;color:var(--taupe);margin-top:5px}\n.nav{display:grid;gap:2px}\n.nav a{display:flex;align-items:center;gap:14px;padding:12px;text-decoration:none;font-family:var(--font-label);text-transform:uppercase;\n  letter-spacing:.18em;font-size:.74rem;color:var(--char);border-radius:2px;position:relative;transition:color .2s,background .2s}\n.nav a:hover{color:var(--ink);background:var(--paper-2)}\n.nav a[aria-current=\"page\"]{color:var(--ink);background:var(--paper-2)}\n.nav a[aria-current=\"page\"]::before{content:\"\";position:absolute;left:-18px;top:10px;bottom:10px;width:1.5px;background:var(--maroon)}\n.cuenta{font-family:var(--font-body);letter-spacing:0;font-weight:500;background:var(--maroon);color:var(--paper);display:grid;place-items:center}\n.nav .cuenta{margin-left:auto;font-size:.7rem;min-width:22px;height:22px;padding:0 6px;border-radius:11px}\n.rail-pie{margin-top:auto;padding:18px 0 0 10px;border-top:1px solid var(--line-2);display:flex;align-items:center;justify-content:space-between;gap:8px}\n.rail-pie small{font-size:.84rem;color:var(--taupe);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n\n.barra-movil,.tabs-movil{display:none}\n\nmain{padding:44px clamp(20px,4vw,56px) 90px;max-width:1320px;width:100%}\nmain:focus{outline:none}\n.cabeza{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:32px}\n.cabeza h1{font-family:var(--font-display);font-weight:400;font-size:clamp(2.4rem,4.4vw,3.7rem);line-height:.95;letter-spacing:-.015em}\n.mes{display:flex;align-items:center;border:1px solid var(--line);border-radius:2px;background:var(--field)}\n.mes button{padding:11px;color:var(--char);display:grid;place-items:center}\n.mes button:hover{color:var(--maroon)}\n.mes button[disabled]{opacity:.28;pointer-events:none}\n.mes button .ico{width:16px;height:16px}\n.mes output{font-family:var(--font-label);text-transform:uppercase;letter-spacing:.16em;font-size:.7rem;min-width:124px;text-align:center}\n\n/* ---------- libro: ingresos, gastos, ganancia ---------- */\n.libro{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border-top:1px solid var(--ink);border-bottom:1px solid var(--line);margin-bottom:34px}\n.libro > div{display:flex;flex-direction:column-reverse;justify-content:flex-end;padding:22px 24px 20px 0}\n.libro > div + div{padding-left:24px;border-left:1px solid var(--line)}\n.libro dt{font-family:var(--font-label);text-transform:uppercase;letter-spacing:.2em;font-size:.66rem;color:var(--taupe);margin-top:10px}\n.libro dd{font-family:var(--font-display);font-size:clamp(2rem,3.6vw,3.1rem);line-height:1;letter-spacing:-.01em;white-space:nowrap}\n.libro dd small{font-size:.5em;color:var(--taupe);margin-right:.06em;vertical-align:.6em}\n.libro .neg dd{color:var(--maroon)}\n.aviso{display:flex;align-items:center;gap:10px;margin:-16px 0 28px;font-size:.92rem;color:var(--char)}\n.aviso .ico{color:var(--maroon);width:18px;height:18px}\n.aviso button{text-decoration:underline;text-underline-offset:3px;color:var(--maroon)}\n\n/* ---------- filtros ---------- */\n.filtros{display:flex;gap:6px;overflow-x:auto;margin:0 -4px 28px;padding:2px 4px;scrollbar-width:none}\n.filtros::-webkit-scrollbar{display:none}\n.chip{flex:none;display:inline-flex;align-items:center;gap:8px;padding:9px 14px;border:1px solid var(--line);border-radius:999px;\n  font-family:var(--font-label);text-transform:uppercase;letter-spacing:.14em;font-size:.68rem;color:var(--char);transition:background .2s,color .2s,border-color .2s}\n.chip:hover{border-color:var(--ink);color:var(--ink)}\n.chip[aria-pressed=\"true\"]{background:var(--ink);border-color:var(--ink);color:var(--paper)}\n.chip b{font-family:var(--font-body);font-weight:500;letter-spacing:0;font-size:.74rem;opacity:.65}\n\n/* ---------- pedidos ---------- */\n.mesa{display:grid;gap:30px 22px;grid-template-columns:repeat(auto-fill,minmax(212px,1fr))}\n.pedido{text-align:left;display:flex;flex-direction:column;gap:12px;animation:sube .55s var(--ease) both;animation-delay:calc(var(--i,0) * 35ms);min-width:0}\n.lamina{position:relative;background:var(--paper-2);border-radius:2px;overflow:hidden;display:grid;place-items:center;\n  transition:transform .45s var(--ease),box-shadow .45s var(--ease)}\n.pedido .lamina{aspect-ratio:4/5;width:100%}\n.pedido:hover .lamina{transform:translateY(-4px);box-shadow:0 18px 30px -22px rgba(5,4,3,.45)}\n.lamina > img{width:100%;height:100%;object-fit:contain;padding:12px}\n.placa{display:grid;place-items:center;gap:12px;padding:18px;text-align:center}\n.placa .estilo{font-family:var(--font-display);font-style:italic;font-size:1.6rem;line-height:1.05;color:var(--char)}\n.placa .pastas{display:flex;gap:6px}\n.placa .pastas i{width:26px;height:26px;border-radius:50%;border:1px solid var(--line);display:block}\n.placa small{font-family:var(--font-label);text-transform:uppercase;letter-spacing:.2em;font-size:.58rem;color:var(--taupe)}\n.sello{position:absolute;left:10px;top:10px;display:inline-flex;align-items:center;gap:7px;padding:6px 10px 6px 9px;background:var(--paper);border-radius:999px;\n  font-family:var(--font-label);text-transform:uppercase;letter-spacing:.16em;font-size:.58rem;box-shadow:0 2px 8px -4px rgba(5,4,3,.3)}\n.sello::before{content:\"\";width:7px;height:7px;border-radius:50%;background:currentColor}\n.e-nuevo{color:var(--maroon)} .e-armando{color:var(--brown)} .e-listo{color:var(--blue)} .e-entregado,.e-cancelado{color:var(--taupe)}\n.sello.e-cancelado::before{background:transparent;border:1px solid currentColor}\n.pedido .quien{display:flex;justify-content:space-between;align-items:baseline;gap:10px;min-width:0}\n.pedido .quien b{font-weight:500;font-size:1rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0}\n.pedido .quien span{font-family:var(--font-display);font-size:1.35rem;line-height:1;flex:none}\n.pedido .quien span.falta{font-family:var(--font-label);text-transform:uppercase;letter-spacing:.14em;font-size:.6rem;color:var(--maroon)}\n.pedido .det{font-size:.84rem;color:var(--taupe);margin-top:-8px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.pedido.cancelado .lamina{opacity:.5}\n\n.vacio{grid-column:1/-1;padding:72px 20px;text-align:center;border:1px dashed var(--line);border-radius:2px}\n.vacio .ico{width:34px;height:34px;color:var(--stone);margin:0 auto 16px;stroke-width:1.1}\n.vacio h3{font-family:var(--font-display);font-weight:400;font-size:1.8rem;line-height:1.1}\n.vacio p{color:var(--taupe);font-weight:300;max-width:44ch;margin:8px auto 0}\n.cargando{grid-column:1/-1;display:grid;gap:22px;grid-template-columns:repeat(auto-fill,minmax(212px,1fr))}\n.cargando i{display:block;aspect-ratio:4/5;background:linear-gradient(100deg,var(--paper-2) 40%,var(--paper-3) 50%,var(--paper-2) 60%);background-size:200% 100%;animation:brillo 1.4s linear infinite;border-radius:2px}\n\n/* ---------- hoja lateral ---------- */\ndialog.hoja{margin:0 0 0 auto;height:100vh;height:100dvh;max-height:none;width:min(560px,100vw);max-width:100vw;border:none;background:var(--paper);color:var(--ink);\n  padding:0;box-shadow:-24px 0 60px -30px rgba(5,4,3,.45)}\ndialog.hoja[open]{animation:entraLado .5s var(--ease)}\ndialog.hoja::backdrop{background:rgba(5,4,3,.34);animation:aparece .3s ease}\n.hoja-marco{height:100%;display:flex;flex-direction:column}\n.hoja-cab{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:18px 22px;border-bottom:1px solid var(--line)}\n.hoja-cab h2{font-family:var(--font-display);font-weight:400;font-size:1.65rem;line-height:1.1}\n.hoja-cab .cerrar{padding:10px;margin:-10px;color:var(--char)}\n.hoja-cab .cerrar:hover{color:var(--maroon)}\n.hoja-cuerpo{flex:1;overflow-y:auto;padding:24px 22px 32px;overscroll-behavior:contain}\n.hoja-pie{padding:14px 22px calc(14px + env(safe-area-inset-bottom,0px));border-top:1px solid var(--line);display:flex;gap:10px;justify-content:space-between;align-items:center}\n.hoja-pie .btn-ink{flex:1}\n\n.foto-grande{height:min(52vh,440px);margin-bottom:24px}\n.foto-grande > img{padding:18px}\n.folio{display:flex;justify-content:space-between;align-items:baseline;gap:12px;flex-wrap:wrap;margin-bottom:6px}\n.folio b{font-family:var(--font-display);font-weight:400;font-size:2.1rem;line-height:1}\n.folio span{font-size:.84rem;color:var(--taupe)}\n.ig{display:inline-flex;align-items:center;gap:8px;font-size:1.02rem;margin-bottom:28px}\n.ig .ico{width:17px;height:17px}\n.bloque-t{font-family:var(--font-label);text-transform:uppercase;letter-spacing:.2em;font-size:.66rem;color:var(--taupe);font-weight:400;margin-bottom:14px}\n\n.pasos{display:grid;grid-template-columns:repeat(4,1fr);margin:4px 0 8px;position:relative}\n.pasos::before,.pasos .avance{content:\"\";position:absolute;left:12.5%;top:15px;height:1px}\n.pasos::before{right:12.5%;background:var(--line)}\n.pasos .avance{width:75%;background:var(--ink);transform-origin:left;transition:transform .5s var(--ease)}\n.paso{position:relative;display:grid;justify-items:center;gap:9px;padding:0 2px;font-family:var(--font-label);text-transform:uppercase;letter-spacing:.12em;font-size:.6rem;color:var(--taupe)}\n.paso i{width:31px;height:31px;border-radius:50%;border:1px solid var(--line);background:var(--paper);display:grid;place-items:center;transition:background .3s,border-color .3s,box-shadow .3s}\n.paso i .ico{width:14px;height:14px}\n.paso:hover i{border-color:var(--ink)}\n.paso.hecho{color:var(--ink)} .paso.hecho i{background:var(--ink);border-color:var(--ink);color:var(--paper)}\n.paso.actual{color:var(--ink)} .paso.actual i{border-color:var(--maroon);box-shadow:0 0 0 4px rgba(146,41,57,.13)}\n.paso.actual i::after{content:\"\";width:9px;height:9px;border-radius:50%;background:var(--maroon)}\n.cancelar-fila{text-align:center;margin-bottom:28px}\n\n.ficha{border-top:1px solid var(--ink);margin-bottom:28px}\n.ficha > div{display:grid;grid-template-columns:120px 1fr;gap:14px;padding:11px 0;border-bottom:1px solid var(--line-2);font-size:.95rem}\n.ficha dt{font-family:var(--font-label);text-transform:uppercase;letter-spacing:.14em;font-size:.62rem;color:var(--taupe);padding-top:4px}\n.piezas{list-style:none;display:grid;gap:4px}\n.piezas li{display:flex;justify-content:space-between;gap:10px}\n.piezas li span{color:var(--taupe)}\n.dinero{display:flex;align-items:center;gap:16px;margin-bottom:28px}\n.dinero small{color:var(--taupe);font-size:.84rem;line-height:1.35}\n.monto{position:relative}\n.monto::before{content:\"$\";position:absolute;left:13px;top:50%;transform:translateY(-52%);font-family:var(--font-display);font-size:1.3rem;color:var(--taupe);pointer-events:none}\n.monto .in{padding-left:30px;font-family:var(--font-display);font-size:1.45rem;padding-block:8px}\n.dinero .monto{width:170px;flex:none}\n.calculado{font-family:var(--font-display);font-size:2.2rem;line-height:1}\n\n/* ---------- gastos ---------- */\n.dos{display:grid;grid-template-columns:minmax(0,370px) minmax(0,1fr);gap:clamp(28px,4.5vw,64px);align-items:start}\n.alta{position:sticky;top:28px;background:var(--paper-2);padding:26px 24px;border-radius:2px;display:grid;gap:18px}\n.alta h2{font-family:var(--font-display);font-weight:400;font-size:1.75rem;line-height:1}\n.alta .in{background:var(--paper)}\n.alta .monto .in{font-size:2.4rem;padding-block:8px;padding-left:34px}\n.alta .monto::before{font-size:1.7rem;left:14px}\n.cats{display:flex;flex-wrap:wrap;gap:6px}\n.cats .chip{padding:8px 12px}\n.reparto{margin-bottom:38px}\n.barra{display:grid;grid-template-columns:118px 1fr 90px;gap:14px;align-items:center;padding:7px 0;font-size:.9rem}\n.barra .num{text-align:right}\n.barra .riel{height:6px;background:var(--paper-2);border-radius:3px;overflow:hidden}\n.barra .riel i{display:block;height:100%;background:var(--char);border-radius:3px;transform-origin:left;animation:crece .9s var(--ease) both}\n.reparto .barra:first-of-type .riel i{background:var(--maroon)}\n.dia{margin-bottom:24px}\n.dia h4{display:flex;justify-content:space-between;gap:10px;font-family:var(--font-label);text-transform:uppercase;letter-spacing:.16em;font-size:.64rem;color:var(--taupe);font-weight:400;padding-bottom:8px;border-bottom:1px solid var(--ink)}\n.gasto{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:12px;align-items:center;padding:12px 0;border-bottom:1px solid var(--line-2)}\n.gasto b{font-weight:400;display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.gasto small{display:block;font-size:.8rem;color:var(--taupe)}\n.gasto .cifra{font-family:var(--font-display);font-size:1.35rem}\n.gasto .quitar{padding:9px;margin-right:-9px;color:var(--taupe)}\n.gasto .quitar:hover{color:var(--maroon)}\n.gasto .quitar .ico{width:15px;height:15px}\n\n/* ---------- catalogo ---------- */\n.seg{display:inline-flex;border:1px solid var(--line);border-radius:2px;padding:3px;gap:2px;margin-bottom:30px;max-width:100%;overflow-x:auto;scrollbar-width:none}\n.seg button{padding:9px 16px;font-family:var(--font-label);text-transform:uppercase;letter-spacing:.14em;font-size:.68rem;color:var(--char);border-radius:1px;white-space:nowrap;transition:background .2s,color .2s}\n.seg button:hover{color:var(--ink)}\n.seg button[aria-pressed=\"true\"]{background:var(--ink);color:var(--paper)}\n.vitrina{display:grid;gap:26px 20px;grid-template-columns:repeat(auto-fill,minmax(176px,1fr))}\n.charm{display:flex;flex-direction:column;gap:10px;min-width:0;animation:sube .5s var(--ease) both;animation-delay:calc(var(--i,0) * 25ms)}\n.charm .lamina{aspect-ratio:1;width:100%}\n.charm .lamina:hover{transform:translateY(-3px);box-shadow:0 14px 26px -20px rgba(5,4,3,.4)}\n.charm .lamina > img{width:78%;height:78%;padding:0;mix-blend-mode:multiply}\n.charm .lamina > .ico{width:30px;height:30px;color:var(--stone)}\n.charm.oculto .lamina > img{opacity:.35;filter:grayscale(1)}\n.charm h3{font-family:var(--font-display);font-weight:400;font-size:1.22rem;line-height:1.1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.charm .linea{display:flex;justify-content:space-between;align-items:center;gap:8px}\n.charm .precio{font-size:.9rem;color:var(--char)}\n.stepper{display:inline-flex;align-items:center;border:1px solid var(--line);border-radius:999px;flex:none}\n.stepper button{width:32px;height:32px;display:grid;place-items:center;color:var(--char)}\n.stepper button:hover{color:var(--maroon)}\n.stepper button .ico{width:14px;height:14px}\n.stepper output{min-width:22px;text-align:center;font-size:.9rem}\n.stepper.cero output{color:var(--maroon)}\n.nuevo{aspect-ratio:1;border:1px dashed var(--stone);border-radius:2px;display:grid;place-content:center;justify-items:center;gap:10px;color:var(--char);\n  font-family:var(--font-label);text-transform:uppercase;letter-spacing:.16em;font-size:.68rem;transition:border-color .25s,color .25s,background .25s}\n.nuevo:hover{border-color:var(--ink);color:var(--ink);background:var(--paper-2)}\n.nuevo .ico{width:26px;height:26px;stroke-width:1.2}\n\n.tarifa{max-width:640px}\n.tarifa section{margin-bottom:36px}\n.tarifa .bloque-t{padding-bottom:10px;border-bottom:1px solid var(--ink);margin-bottom:6px}\n.renglon{display:flex;align-items:center;gap:12px;padding:8px 0}\n.renglon label{font-family:var(--font-display);font-size:1.3rem;line-height:1.15}\n.renglon .puntos{flex:1;align-self:flex-end;border-bottom:1px dotted var(--stone);margin-bottom:14px;min-width:16px}\n.renglon .monto{width:140px;flex:none}\n.renglon .monto .in{font-size:1.25rem;padding-block:6px;text-align:right}\n.guardar-fijo{position:sticky;bottom:20px;display:flex;justify-content:flex-end;max-width:640px}\n\n.nota{color:var(--taupe);font-weight:300;max-width:62ch;margin:-10px 0 22px}\n.nota b{font-weight:500;color:var(--ink)}\n.modelos{max-width:760px;border-top:1px solid var(--ink)}\n.modelo{display:grid;grid-template-columns:minmax(0,1fr) auto 86px;gap:16px;align-items:center;padding:9px 0;border-bottom:1px solid var(--line-2)}\n.modelo b{font-weight:400}\n.modelo .estado{font-family:var(--font-label);text-transform:uppercase;letter-spacing:.14em;font-size:.6rem;color:var(--taupe);text-align:right}\n.modelo .estado.agotado{color:var(--maroon)}\n.modelo .in{padding:8px 10px;text-align:center}\n.interruptor{position:relative;width:46px;height:28px;border-radius:14px;background:var(--stone);transition:background .25s;flex:none}\n.interruptor::after{content:\"\";position:absolute;left:3px;top:3px;width:22px;height:22px;border-radius:50%;background:var(--paper);transition:transform .3s var(--ease);box-shadow:0 1px 3px rgba(5,4,3,.25)}\n.interruptor[aria-checked=\"true\"]{background:var(--ink)}\n.interruptor[aria-checked=\"true\"]::after{transform:translateX(18px)}\n\n/* ---------- fotos ---------- */\n.galeria{display:grid;gap:16px;grid-template-columns:repeat(auto-fill,minmax(172px,1fr))}\n.foto{position:relative;aspect-ratio:1;background:var(--paper-2);border-radius:2px;overflow:hidden;animation:sube .5s var(--ease) both}\n.foto img{width:100%;height:100%;object-fit:cover}\n.foto .quitar{position:absolute;right:8px;top:8px;width:36px;height:36px;border-radius:50%;background:var(--paper);display:grid;place-items:center;color:var(--char);\n  box-shadow:0 4px 12px -6px rgba(5,4,3,.4);opacity:0;transition:opacity .2s,color .2s}\n.foto:hover .quitar,.foto .quitar:focus-visible{opacity:1}\n.foto .quitar:hover{color:var(--maroon)}\n.foto .quitar .ico{width:16px;height:16px}\n.foto .orden{position:absolute;left:8px;bottom:8px;font-size:.72rem;background:var(--paper);padding:2px 9px;border-radius:999px}\n.soltar{aspect-ratio:1;border:1px dashed var(--stone);border-radius:2px;display:grid;place-content:center;justify-items:center;gap:8px;text-align:center;padding:14px;\n  color:var(--char);font-family:var(--font-label);text-transform:uppercase;letter-spacing:.14em;font-size:.66rem;cursor:pointer;transition:border-color .25s,background .25s,color .25s;position:relative;overflow:hidden}\n.soltar:hover,.soltar.encima,.soltar:focus-within{border-color:var(--ink);background:var(--paper-2);color:var(--ink)}\n.soltar .ico{width:26px;height:26px;stroke-width:1.2}\n.soltar small{font-family:var(--font-body);text-transform:none;letter-spacing:0;font-size:.78rem;color:var(--taupe)}\n.soltar input{position:absolute;inset:0;opacity:0;cursor:pointer}\n.soltar.con-foto{padding:0;border-style:solid;border-color:transparent;background:var(--paper-2)}\n.soltar.con-foto img{width:70%;height:70%;object-fit:contain;margin:auto}\n.soltar.con-foto small{position:absolute;bottom:10px;left:0;right:0}\n.forma .soltar{aspect-ratio:auto;height:210px}\n.fila2{display:grid;grid-template-columns:1fr 1fr;gap:14px}\n.forma{display:grid;gap:18px}\n.fila-interruptor{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:14px 0;border-top:1px solid var(--line-2);border-bottom:1px solid var(--line-2)}\n.fila-interruptor span{font-size:.98rem}\n.fila-interruptor small{display:block;color:var(--taupe);font-size:.84rem}\n\n/* ---------- aviso flotante ---------- */\n#toast{position:fixed;left:50%;bottom:calc(26px + env(safe-area-inset-bottom,0px));transform:translate(-50%,16px);background:var(--ink);color:var(--paper);\n  padding:13px 20px;border-radius:2px;font-size:.92rem;opacity:0;pointer-events:none;transition:opacity .25s,transform .35s var(--ease);z-index:90;max-width:min(92vw,460px);\n  box-shadow:0 14px 30px -16px rgba(5,4,3,.6);display:flex;gap:10px;align-items:center}\n#toast.on{opacity:1;transform:translate(-50%,0)}\n#toast.err{background:var(--maroon)}\n#toast .ico{width:16px;height:16px}\n\n@keyframes sube{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}\n@keyframes aparece{from{opacity:0}to{opacity:1}}\n@keyframes entraLado{from{transform:translateX(48px);opacity:.3}to{transform:none;opacity:1}}\n@keyframes entraAbajo{from{transform:translateY(70px);opacity:.3}to{transform:none;opacity:1}}\n@keyframes gira{to{transform:rotate(360deg)}}\n@keyframes brillo{to{background-position:-200% 0}}\n@keyframes crece{from{transform:scaleX(0)}to{transform:scaleX(1)}}\n\n/* ---------- telefono ---------- */\n@media (max-width:860px){\n  .app{grid-template-columns:minmax(0,1fr)}\n  .rail{display:none}\n  .barra-movil{display:flex;position:sticky;top:0;z-index:30;align-items:center;justify-content:space-between;gap:12px;\n    padding:calc(10px + env(safe-area-inset-top,0px)) 16px 10px;background:var(--paper);border-bottom:1px solid var(--line)}\n  .barra-movil .marca{padding:0;gap:10px}\n  .barra-movil .marca img{width:32px;height:32px}\n  .barra-movil .marca b{font-size:1.2rem}\n  .barra-movil .marca span{font-size:.52rem;letter-spacing:.26em;margin-top:3px}\n  .barra-movil .btn-quiet{padding:10px;margin-right:-10px}\n  .tabs-movil{display:grid;grid-template-columns:repeat(4,1fr);position:fixed;left:0;right:0;bottom:0;z-index:40;background:var(--paper);\n    border-top:1px solid var(--line);padding:6px 6px calc(6px + env(safe-area-inset-bottom,0px))}\n  .tabs-movil a{display:grid;justify-items:center;gap:4px;padding:8px 2px;text-decoration:none;color:var(--taupe);font-family:var(--font-label);\n    text-transform:uppercase;letter-spacing:.12em;font-size:.58rem;position:relative;-webkit-tap-highlight-color:transparent}\n  .tabs-movil a[aria-current=\"page\"]{color:var(--ink)}\n  .tabs-movil a[aria-current=\"page\"]::before{content:\"\";position:absolute;top:-7px;left:32%;right:32%;height:1.5px;background:var(--maroon)}\n  .tabs-movil .ico{width:22px;height:22px}\n  .tabs-movil .cuenta{position:absolute;top:2px;left:calc(50% + 6px);min-width:17px;height:17px;padding:0 4px;border-radius:9px;font-size:.62rem}\n  main{padding:24px 16px calc(100px + env(safe-area-inset-bottom,0px))}\n  .cabeza{margin-bottom:22px;align-items:center}\n  .cabeza h1{font-size:2.5rem}\n  .mes output{min-width:104px;font-size:.64rem;letter-spacing:.12em}\n  .mes button{padding:10px 8px}\n  .libro{margin-bottom:26px}\n  .libro > div{padding:16px 8px 14px 0}\n  .libro > div + div{padding-left:12px}\n  .libro dd{font-size:clamp(1.3rem,6.3vw,2rem)}\n  .libro dt{font-size:.54rem;letter-spacing:.14em;margin-top:8px}\n  .aviso{margin:-12px 0 22px;font-size:.86rem;align-items:flex-start}\n  .aviso .ico{margin-top:2px}\n  .filtros{margin-inline:-16px;padding-inline:16px;margin-bottom:22px}\n  .mesa{grid-template-columns:repeat(2,minmax(0,1fr));gap:24px 12px}\n  .cargando{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}\n  .pedido .quien{flex-direction:column;align-items:flex-start;gap:3px}\n  .pedido .quien b{font-size:.92rem;max-width:100%}\n  .pedido .quien span{font-size:1.2rem}\n  .pedido .det{margin-top:-8px;font-size:.78rem}\n  .placa{padding:10px;gap:10px}\n  .placa .estilo{font-size:1.2rem}\n  .placa .pastas i{width:22px;height:22px}\n  .sello{left:7px;top:7px;padding:5px 8px 5px 7px;font-size:.52rem;gap:5px;letter-spacing:.12em}\n  dialog.hoja{margin:auto 0 0;width:100vw;height:calc(100dvh - 24px);border-radius:14px 14px 0 0;box-shadow:0 -20px 50px -30px rgba(5,4,3,.5)}\n  dialog.hoja[open]{animation:entraAbajo .5s var(--ease)}\n  .hoja-cab{padding:14px 18px}\n  .hoja-cuerpo{padding:20px 18px 28px}\n  .hoja-pie{padding-inline:18px}\n  .foto-grande{height:min(46vh,380px)}\n  .dos{grid-template-columns:minmax(0,1fr)}\n  .alta{position:static;padding:20px 18px}\n  .vitrina{grid-template-columns:repeat(2,minmax(0,1fr));gap:22px 12px}\n  .galeria{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}\n  .foto .quitar{opacity:1}\n  .barra{grid-template-columns:92px 1fr 78px;gap:10px;font-size:.84rem}\n  .renglon label{font-size:1.12rem}\n  .renglon .monto{width:116px}\n  .modelo{grid-template-columns:minmax(0,1fr) 78px;row-gap:2px}\n  .modelo .estado{grid-row:2;text-align:left}\n  .modelo .in{grid-row:1 / span 2;grid-column:2}\n  .ficha > div{grid-template-columns:92px 1fr}\n  .dinero{flex-wrap:wrap}\n  .guardar-fijo{bottom:calc(86px + env(safe-area-inset-bottom,0px))}\n  .guardar-fijo .btn{width:100%}\n  #toast{bottom:calc(90px + env(safe-area-inset-bottom,0px))}\n}\n@media (max-width:360px){\n  .charm .linea{flex-direction:column;align-items:flex-start}\n}\n@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;animation-delay:0ms!important;transition-duration:.01ms!important}}\n</style>\n</head>\n<body>\n\n<svg width=\"0\" height=\"0\" style=\"position:absolute\" aria-hidden=\"true\">\n  <symbol id=\"i-pedidos\" viewBox=\"0 0 24 24\"><path d=\"M5 8h14l-1.2 11.2a2 2 0 0 1-2 1.8H8.2a2 2 0 0 1-2-1.8L5 8Z\"/><path d=\"M9 8V6.5a3 3 0 0 1 6 0V8\"/></symbol>\n  <symbol id=\"i-gastos\" viewBox=\"0 0 24 24\"><path d=\"M6 3h12v18l-2.4-1.6L13.2 21 12 20.2 10.8 21l-2.4-1.6L6 21V3Z\"/><path d=\"M9.5 8h5M9.5 11.5h5M9.5 15h3\"/></symbol>\n  <symbol id=\"i-catalogo\" viewBox=\"0 0 24 24\"><path d=\"m12 3 2.3 5.6 6 .5-4.6 3.9 1.4 5.9L12 15.8 6.9 18.9l1.4-5.9L3.7 9.1l6-.5L12 3Z\"/></symbol>\n  <symbol id=\"i-fotos\" viewBox=\"0 0 24 24\"><rect x=\"3.5\" y=\"4.5\" width=\"17\" height=\"15\" rx=\"1.5\"/><circle cx=\"9\" cy=\"10\" r=\"1.6\"/><path d=\"m4 17 5-4.5 3.5 3 3-2.5 4.5 4\"/></symbol>\n  <symbol id=\"i-salir\" viewBox=\"0 0 24 24\"><path d=\"M14 4h4.5A1.5 1.5 0 0 1 20 5.5v13a1.5 1.5 0 0 1-1.5 1.5H14\"/><path d=\"M10 16l-4-4 4-4M6 12h10\"/></symbol>\n  <symbol id=\"i-mas\" viewBox=\"0 0 24 24\"><path d=\"M12 5v14M5 12h14\"/></symbol>\n  <symbol id=\"i-menos\" viewBox=\"0 0 24 24\"><path d=\"M5 12h14\"/></symbol>\n  <symbol id=\"i-x\" viewBox=\"0 0 24 24\"><path d=\"M6 6l12 12M18 6 6 18\"/></symbol>\n  <symbol id=\"i-izq\" viewBox=\"0 0 24 24\"><path d=\"m15 5-7 7 7 7\"/></symbol>\n  <symbol id=\"i-der\" viewBox=\"0 0 24 24\"><path d=\"m9 5 7 7-7 7\"/></symbol>\n  <symbol id=\"i-ok\" viewBox=\"0 0 24 24\"><path d=\"m5 12.5 4.5 4.5L19 7.5\"/></symbol>\n  <symbol id=\"i-ig\" viewBox=\"0 0 24 24\"><rect x=\"3.5\" y=\"3.5\" width=\"17\" height=\"17\" rx=\"5\"/><circle cx=\"12\" cy=\"12\" r=\"4\"/><circle cx=\"17.2\" cy=\"6.8\" r=\".6\" fill=\"currentColor\"/></symbol>\n  <symbol id=\"i-subir\" viewBox=\"0 0 24 24\"><path d=\"M12 16V4M7 9l5-5 5 5\"/><path d=\"M4 15v3.5A1.5 1.5 0 0 0 5.5 20h13a1.5 1.5 0 0 0 1.5-1.5V15\"/></symbol>\n  <symbol id=\"i-alerta\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"8.5\"/><path d=\"M12 7.5v5.5M12 16.2v.3\"/></symbol>\n  <symbol id=\"i-ojo\" viewBox=\"0 0 24 24\"><path d=\"M2.5 12S6 5.5 12 5.5 21.5 12 21.5 12 18 18.5 12 18.5 2.5 12 2.5 12Z\"/><circle cx=\"12\" cy=\"12\" r=\"2.8\"/></symbol>\n</svg>\n\n<!-- ============ entrada ============ -->\n<div class=\"login\" id=\"login\" hidden>\n  <div class=\"login-box\">\n    <img src=\"__LOGO__\" alt=\"\">\n    <h1>El <i>taller</i></h1>\n    <p class=\"lead\">Pedidos, gastos y catálogo de ASTÉRIA.</p>\n    <form id=\"form-login\" novalidate>\n      <div class=\"campo\"><label for=\"l-usuario\">Usuario</label><input class=\"in\" id=\"l-usuario\" name=\"username\" autocomplete=\"username\" autocapitalize=\"none\" spellcheck=\"false\"></div>\n      <div class=\"campo\"><label for=\"l-pass\">Contraseña</label>\n        <div class=\"pass\"><input class=\"in\" id=\"l-pass\" name=\"password\" type=\"password\" autocomplete=\"current-password\">\n          <button type=\"button\" id=\"ver-pass\" aria-label=\"Mostrar contraseña\" aria-pressed=\"false\"><svg class=\"ico\"><use href=\"#i-ojo\"/></svg></button></div></div>\n      <p class=\"err\" id=\"l-err\" role=\"alert\"></p>\n      <button class=\"btn btn-ink btn-full\" id=\"l-entrar\" type=\"submit\">Entrar</button>\n    </form>\n  </div>\n</div>\n\n<!-- ============ taller ============ -->\n<div class=\"app\" id=\"app\" hidden>\n  <aside class=\"rail\" aria-label=\"Secciones\">\n    <div class=\"marca\"><img src=\"__LOGO__\" alt=\"\"><div><b>ASTÉRIA</b><span>Taller</span></div></div>\n    <nav class=\"nav\" data-nav>\n      <a href=\"#pedidos\" data-vista=\"pedidos\"><svg class=\"ico\"><use href=\"#i-pedidos\"/></svg>Pedidos<span class=\"cuenta\" data-cuenta hidden></span></a>\n      <a href=\"#gastos\" data-vista=\"gastos\"><svg class=\"ico\"><use href=\"#i-gastos\"/></svg>Gastos</a>\n      <a href=\"#catalogo\" data-vista=\"catalogo\"><svg class=\"ico\"><use href=\"#i-catalogo\"/></svg>Catálogo</a>\n      <a href=\"#fotos\" data-vista=\"fotos\"><svg class=\"ico\"><use href=\"#i-fotos\"/></svg>Fotos</a>\n    </nav>\n    <div class=\"rail-pie\"><small data-usuario></small><button class=\"btn btn-quiet btn-sm\" data-salir><svg class=\"ico\"><use href=\"#i-salir\"/></svg>Salir</button></div>\n  </aside>\n\n  <header class=\"barra-movil\">\n    <div class=\"marca\"><img src=\"__LOGO__\" alt=\"\"><div><b>ASTÉRIA</b><span>Taller</span></div></div>\n    <button class=\"btn btn-quiet\" data-salir aria-label=\"Salir\"><svg class=\"ico\"><use href=\"#i-salir\"/></svg></button>\n  </header>\n\n  <main id=\"vista\" tabindex=\"-1\"></main>\n\n  <nav class=\"tabs-movil\" data-nav aria-label=\"Secciones\">\n    <a href=\"#pedidos\" data-vista=\"pedidos\"><svg class=\"ico\"><use href=\"#i-pedidos\"/></svg>Pedidos<span class=\"cuenta\" data-cuenta hidden></span></a>\n    <a href=\"#gastos\" data-vista=\"gastos\"><svg class=\"ico\"><use href=\"#i-gastos\"/></svg>Gastos</a>\n    <a href=\"#catalogo\" data-vista=\"catalogo\"><svg class=\"ico\"><use href=\"#i-catalogo\"/></svg>Catálogo</a>\n    <a href=\"#fotos\" data-vista=\"fotos\"><svg class=\"ico\"><use href=\"#i-fotos\"/></svg>Fotos</a>\n  </nav>\n</div>\n\n<dialog class=\"hoja\" id=\"hoja\" aria-labelledby=\"hoja-titulo\">\n  <div class=\"hoja-marco\">\n    <div class=\"hoja-cab\"><h2 id=\"hoja-titulo\"></h2><button class=\"cerrar\" data-cerrar aria-label=\"Cerrar\"><svg class=\"ico\"><use href=\"#i-x\"/></svg></button></div>\n    <div class=\"hoja-cuerpo\" id=\"hoja-cuerpo\"></div>\n    <div class=\"hoja-pie\" id=\"hoja-pie\"></div>\n  </div>\n</dialog>\n\n<div id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n\n<script>\n(function () {\n  \"use strict\";\n  const MODELOS = __MODELOS__;\n  const ESTADOS = [\"nuevo\", \"armando\", \"listo\", \"entregado\"];\n  const NOMBRE_ESTADO = { nuevo: \"Nuevo\", armando: \"Armando\", listo: \"Listo\", entregado: \"Entregado\", cancelado: \"Cancelado\" };\n  const CATEGORIAS_GASTO = [\"Material\", \"Charms\", \"Fundas\", \"Envíos\", \"Empaque\", \"Publicidad\", \"Herramienta\", \"Otro\"];\n  const MESES = [\"enero\", \"febrero\", \"marzo\", \"abril\", \"mayo\", \"junio\", \"julio\", \"agosto\", \"septiembre\", \"octubre\", \"noviembre\", \"diciembre\"];\n  const COLOR = { Blanca: \"#fbfaf7\", Negra: \"#151311\", Gris: \"#9b9b98\", Beige: \"#dcc9ae\" };\n\n  const $ = (s, r) => (r || document).querySelector(s);\n  const $$ = (s, r) => Array.from((r || document).querySelectorAll(s));\n  const esc = (s) => String(s == null ? \"\" : s).replace(/[&<>\"']/g, (c) => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" }[c]));\n  const icono = (n) => '<svg class=\"ico\" aria-hidden=\"true\"><use href=\"#i-' + n + '\"/></svg>';\n  const pesos = (n) => n == null ? \"—\" : \"$\" + Number(n).toLocaleString(\"es-MX\", { maximumFractionDigits: 2 });\n  const hoyIso = () => { const d = new Date(); return new Date(d.getTime() - d.getTimezoneOffset() * 6e4).toISOString().slice(0, 10); };\n  const totalDe = (p) => typeof p.total === \"number\" ? p.total : typeof p.totalManual === \"number\" ? p.totalManual : null;\n\n  const S = {\n    usuario: null, mes: hoyIso().slice(0, 7), filtro: \"activos\",\n    pedidos: null, rend: null, gastos: null, catalogo: null, charms: null, precios: null,\n    subCat: \"charms\", estiloStock: null, seccionFoto: null, catGasto: \"Material\",\n  };\n\n  /* ---------- avisos ---------- */\n  let toastT;\n  function avisar(msg, error) {\n    const t = $(\"#toast\");\n    t.innerHTML = icono(error ? \"alerta\" : \"ok\") + \"<span>\" + esc(msg) + \"</span>\";\n    t.className = \"on\" + (error ? \" err\" : \"\");\n    clearTimeout(toastT);\n    toastT = setTimeout(() => { t.className = \"\"; }, error ? 4200 : 2600);\n  }\n  const ERRORES = {\n    monto_requerido: \"Escribe el monto del gasto.\",\n    imagen_muy_grande: \"La foto pesa demasiado aun comprimida. Prueba con otra.\",\n    tipo_no_permitido: \"Ese archivo no es una foto. Usa JPG, PNG o WebP.\",\n    no_encontrado: \"Eso ya no existe. Recarga la página.\",\n  };\n\n  /* ---------- api ---------- */\n  async function api(ruta, op) {\n    op = op || {};\n    const headers = {};\n    let body = op.body;\n    if (op.json !== undefined) { headers[\"Content-Type\"] = \"application/json\"; body = JSON.stringify(op.json); }\n    if (op.tipo) headers[\"Content-Type\"] = op.tipo;\n    let res;\n    try {\n      res = await fetch(ruta, { method: op.method || \"GET\", headers, body, credentials: \"same-origin\" });\n    } catch (e) {\n      avisar(\"Sin conexión. Revisa tu internet e intenta de nuevo.\", true);\n      throw e;\n    }\n    let data = null;\n    try { data = await res.json(); } catch (e) { data = null; }\n    if (res.status === 401) { mostrarLogin(); throw new Error(\"sesion\"); }\n    if (!res.ok || (data && data.ok === false)) {\n      const code = data && data.error;\n      avisar(ERRORES[code] || \"No se pudo guardar. Intenta de nuevo.\", true);\n      throw new Error(code || \"error\");\n    }\n    return data;\n  }\n\n  /* ---------- entrada ---------- */\n  function mostrarLogin() {\n    $(\"#app\").hidden = true;\n    $(\"#login\").hidden = false;\n    if (hoja.open) hoja.close();\n    setTimeout(() => $(\"#l-usuario\").focus(), 60);\n  }\n  $(\"#ver-pass\").addEventListener(\"click\", (e) => {\n    const i = $(\"#l-pass\"), ver = i.type === \"password\";\n    i.type = ver ? \"text\" : \"password\";\n    e.currentTarget.setAttribute(\"aria-pressed\", String(ver));\n    e.currentTarget.setAttribute(\"aria-label\", ver ? \"Ocultar contraseña\" : \"Mostrar contraseña\");\n  });\n  $(\"#form-login\").addEventListener(\"submit\", async (e) => {\n    e.preventDefault();\n    const err = $(\"#l-err\"), btn = $(\"#l-entrar\");\n    const usuario = $(\"#l-usuario\").value.trim(), contrasena = $(\"#l-pass\").value;\n    if (!usuario || !contrasena) { err.textContent = \"Escribe tu usuario y tu contraseña.\"; return; }\n    err.textContent = \"\"; btn.classList.add(\"ocupado\");\n    try {\n      const res = await fetch(\"/admin/login\", { method: \"POST\", headers: { \"Content-Type\": \"application/json\" }, credentials: \"same-origin\",\n        body: JSON.stringify({ usuario, contrasena }) });\n      const d = await res.json().catch(() => ({}));\n      if (res.ok && d.ok) { $(\"#l-pass\").value = \"\"; arrancar(d.usuario); return; }\n      if (d.error === \"demasiados_intentos\") err.textContent = \"Demasiados intentos. Espera \" + (d.minutos || 15) + \" minutos y vuelve a probar.\";\n      else if (d.error === \"acceso_sin_configurar\") err.textContent = \"Falta configurar el usuario del panel en Cloudflare.\";\n      else err.textContent = \"Usuario o contraseña incorrectos.\" + (d.restantes > 0 && d.restantes <= 2 ? \" Te quedan \" + d.restantes + \" intentos.\" : \"\");\n      $(\"#l-pass\").select();\n    } catch (x) {\n      err.textContent = \"Sin conexión. Revisa tu internet.\";\n    } finally { btn.classList.remove(\"ocupado\"); }\n  });\n  $$(\"[data-salir]\").forEach((b) => b.addEventListener(\"click\", async () => {\n    try { await fetch(\"/admin/logout\", { method: \"POST\", credentials: \"same-origin\" }); } catch (e) { /* igual se sale */ }\n    Object.assign(S, { pedidos: null, rend: null, gastos: null, charms: null, precios: null, catalogo: null });\n    mostrarLogin();\n  }));\n\n  /* ---------- hoja lateral ---------- */\n  const hoja = $(\"#hoja\");\n  function abrirHoja(titulo, cuerpo, pie) {\n    $(\"#hoja-titulo\").textContent = titulo;\n    $(\"#hoja-cuerpo\").innerHTML = cuerpo;\n    $(\"#hoja-pie\").innerHTML = pie || \"\";\n    $(\"#hoja-pie\").hidden = !pie;\n    if (!hoja.open) { hoja.showModal(); $(\"#hoja-cuerpo\").scrollTop = 0; }\n  }\n  // Clic en el fondo oscuro (fuera del marco) cierra, igual que la X y Esc.\n  hoja.addEventListener(\"click\", (e) => { if (e.target === hoja || e.target.closest(\"[data-cerrar]\")) hoja.close(); });\n\n  /* ---------- navegacion ---------- */\n  const VISTAS = { pedidos: vistaPedidos, gastos: vistaGastos, catalogo: vistaCatalogo, fotos: vistaFotos };\n  function ir() {\n    const v = (location.hash || \"#pedidos\").slice(1);\n    const vista = VISTAS[v] ? v : \"pedidos\";\n    $$(\"[data-nav] a\").forEach((a) => { if (a.dataset.vista === vista) a.setAttribute(\"aria-current\", \"page\"); else a.removeAttribute(\"aria-current\"); });\n    if (hoja.open) hoja.close();\n    VISTAS[vista]();\n    window.scrollTo(0, 0);\n  }\n  window.addEventListener(\"hashchange\", ir);\n\n  const nombreMes = (ym) => { const [y, m] = ym.split(\"-\").map(Number); return MESES[m - 1] + \" \" + y; };\n  const moverMes = (ym, d) => { const [y, m] = ym.split(\"-\").map(Number); const f = new Date(y, m - 1 + d, 1); return f.getFullYear() + \"-\" + String(f.getMonth() + 1).padStart(2, \"0\"); };\n  function selectorMes() {\n    return '<div class=\"mes\"><button data-mes=\"-1\" aria-label=\"Mes anterior\">' + icono(\"izq\") + '</button><output aria-live=\"polite\">' + nombreMes(S.mes) +\n      '</output><button data-mes=\"1\" aria-label=\"Mes siguiente\"' + (S.mes >= hoyIso().slice(0, 7) ? \" disabled\" : \"\") + \">\" + icono(\"der\") + \"</button></div>\";\n  }\n  function engancharMes(recargar) {\n    $$(\"[data-mes]\").forEach((b) => b.addEventListener(\"click\", () => {\n      S.mes = moverMes(S.mes, Number(b.dataset.mes)); S.pedidos = null; S.rend = null; recargar();\n    }));\n  }\n  function actualizarCuenta() {\n    const n = (S.pedidos || []).filter((p) => p.estado === \"nuevo\").length;\n    $$(\"[data-cuenta]\").forEach((c) => { c.hidden = !n; c.textContent = n; c.setAttribute(\"aria-label\", n + \" nuevos\"); });\n  }\n  const vacio = (ico, titulo, texto) => '<div class=\"vacio\">' + icono(ico) + \"<h3>\" + esc(titulo) + \"</h3><p>\" + esc(texto) + \"</p></div>\";\n  const rangoMes = () => \"desde=\" + S.mes + \"-01&hasta=\" + S.mes + \"-31\";\n\n  /* =================== PEDIDOS =================== */\n  async function vistaPedidos() {\n    $(\"#vista\").innerHTML =\n      '<div class=\"cabeza\"><h1>Pedidos</h1>' + selectorMes() + \"</div>\" +\n      '<dl class=\"libro\" id=\"libro\">' + libroHtml() + '</dl><div id=\"aviso\"></div>' +\n      '<div class=\"filtros\" id=\"filtros\" role=\"group\" aria-label=\"Filtrar por estado\"></div>' +\n      '<div class=\"mesa\" id=\"mesa\"><div class=\"cargando\">' + \"<i></i>\".repeat(6) + \"</div></div>\";\n    engancharMes(vistaPedidos);\n    try {\n      const [p, r] = await Promise.all([\n        S.pedidos ? { pedidos: S.pedidos } : api(\"/admin/pedidos?mes=\" + S.mes),\n        S.rend ? S.rend : api(\"/admin/rendimiento?\" + rangoMes()),\n      ]);\n      S.pedidos = p.pedidos; S.rend = r;\n      if ($(\"#mesa\")) pintarPedidos();\n    } catch (e) {\n      if (e.message !== \"sesion\" && $(\"#mesa\")) $(\"#mesa\").innerHTML = vacio(\"alerta\", \"No se pudieron cargar los pedidos\", \"Revisa tu conexión y vuelve a abrir esta sección.\");\n    }\n  }\n\n  function libroHtml() {\n    const r = S.rend;\n    const cifra = (n) => r ? \"<small>$</small>\" + Math.abs(n).toLocaleString(\"es-MX\", { maximumFractionDigits: 0 }) : \"—\";\n    const neg = r && r.utilidad < 0;\n    return \"<div><dt>Ingresos</dt><dd class=\\\"num\\\">\" + cifra(r && r.ingresos) + \"</dd></div>\" +\n      \"<div><dt>Gastos</dt><dd class=\\\"num\\\">\" + cifra(r && r.gastos) + \"</dd></div>\" +\n      '<div class=\"' + (neg ? \"neg\" : \"\") + '\"><dt>Ganancia</dt><dd class=\"num\">' + (neg ? \"−\" : \"\") + cifra(r && r.utilidad) + \"</dd></div>\";\n  }\n\n  function filtroPedido(f) {\n    return (p) => f === \"todos\" ? true\n      : f === \"activos\" ? [\"nuevo\", \"armando\", \"listo\"].includes(p.estado)\n      : f === \"sinprecio\" ? p.estado !== \"cancelado\" && totalDe(p) === null\n      : p.estado === f;\n  }\n\n  function pintarPedidos() {\n    $(\"#libro\").innerHTML = libroHtml();\n    const lista = S.pedidos || [];\n    const sinPrecio = lista.filter(filtroPedido(\"sinprecio\")).length;\n    $(\"#aviso\").innerHTML = sinPrecio && S.filtro !== \"sinprecio\"\n      ? '<p class=\"aviso\">' + icono(\"alerta\") + \"<span>\" + (sinPrecio === 1 ? \"1 pedido no tiene precio y no suma\" : sinPrecio + \" pedidos no tienen precio y no suman\") +\n        ' a tus ingresos. <button data-sin>Ponles precio</button></span></p>' : \"\";\n    if ($(\"[data-sin]\")) $(\"[data-sin]\").addEventListener(\"click\", () => { S.filtro = \"sinprecio\"; pintarPedidos(); });\n\n    const filtros = [[\"activos\", \"Por hacer\"], [\"nuevo\", \"Nuevos\"], [\"armando\", \"Armando\"], [\"listo\", \"Listos\"], [\"entregado\", \"Entregados\"], [\"todos\", \"Todos\"]];\n    if (sinPrecio || S.filtro === \"sinprecio\") filtros.push([\"sinprecio\", \"Sin precio\"]);\n    if (lista.some((p) => p.estado === \"cancelado\")) filtros.push([\"cancelado\", \"Cancelados\"]);\n    $(\"#filtros\").innerHTML = filtros.map(([k, n]) =>\n      '<button class=\"chip\" data-f=\"' + k + '\" aria-pressed=\"' + (S.filtro === k) + '\">' + n + ' <b class=\"num\">' + lista.filter(filtroPedido(k)).length + \"</b></button>\").join(\"\");\n    $$(\"#filtros .chip\").forEach((b) => b.addEventListener(\"click\", () => { S.filtro = b.dataset.f; pintarPedidos(); }));\n\n    const vis = lista.filter(filtroPedido(S.filtro));\n    const mesa = $(\"#mesa\");\n    if (!lista.length) {\n      mesa.innerHTML = vacio(\"pedidos\", \"Sin pedidos en \" + nombreMes(S.mes), \"Cuando alguien pida desde la página, su pedido aparece aquí con la foto de cómo debe quedar la funda.\");\n    } else if (!vis.length) {\n      mesa.innerHTML = S.filtro === \"activos\"\n        ? vacio(\"ok\", \"Todo al día\", \"No hay pedidos pendientes de armar ni de entregar este mes.\")\n        : vacio(\"pedidos\", \"Nada por aquí\", \"Ningún pedido de \" + nombreMes(S.mes) + \" está en ese estado.\");\n    } else {\n      mesa.innerHTML = vis.map(tarjetaPedido).join(\"\");\n      $$(\".pedido\", mesa).forEach((b) => b.addEventListener(\"click\", () => abrirPedido(b.dataset.clave)));\n    }\n    actualizarCuenta();\n  }\n\n  function relativo(iso) {\n    if (!iso) return \"\";\n    const d = new Date(iso), hoy = new Date();\n    const dias = Math.round((new Date(hoy.toDateString()) - new Date(d.toDateString())) / 864e5);\n    if (dias === 0) return \"hoy, \" + d.toLocaleTimeString(\"es-MX\", { hour: \"numeric\", minute: \"2-digit\" });\n    if (dias === 1) return \"ayer\";\n    if (dias < 7) return \"hace \" + dias + \" días\";\n    return d.toLocaleDateString(\"es-MX\", { day: \"numeric\", month: \"short\" });\n  }\n\n  function laminaPedido(p, grande) {\n    if (p.disenoImg) return '<img src=\"/img/' + esc(p.disenoImg) + '\" alt=\"Diseño de la funda de @' + esc(p.ig) + '\" loading=\"lazy\">';\n    const colores = [p.funda, p.pasta].filter(Boolean).filter((c, i, a) => a.indexOf(c) === i);\n    const transparente = /transparente/i.test(p.style || \"\");\n    const muestras = (transparente ? ['<i title=\"Transparente\" style=\"background:repeating-linear-gradient(45deg,var(--line) 0 2px,transparent 2px 7px)\"></i>'] : [])\n      .concat(colores.map((c) => '<i title=\"' + esc(c) + '\" style=\"background:' + (COLOR[c] || \"var(--stone)\") + '\"></i>')).join(\"\");\n    const estilo = p.tipo === \"charms\" ? \"Con charms\" : (p.style || \"Bedazzled\").replace(/\\s*\\(.*\\)/, \"\");\n    return '<div class=\"placa\"><span class=\"estilo\">' + esc(estilo) + \"</span>\" + (muestras ? '<span class=\"pastas\">' + muestras + \"</span>\" : \"\") +\n      (p.dens ? \"<small>\" + esc(p.dens) + \"</small>\" : \"\") + (grande && p.tipo === \"charms\" ? \"<small>Llegó sin foto del diseño</small>\" : \"\") + \"</div>\";\n  }\n\n  function tarjetaPedido(p, i) {\n    const total = totalDe(p);\n    return '<button class=\"pedido' + (p.estado === \"cancelado\" ? \" cancelado\" : \"\") + '\" data-clave=\"' + esc(p.clave) + '\" style=\"--i:' + Math.min(i, 16) + '\">' +\n      '<span class=\"lamina\">' + laminaPedido(p) + '<span class=\"sello e-' + p.estado + '\">' + NOMBRE_ESTADO[p.estado] + \"</span>\" + \"</span>\" +\n      '<span class=\"quien\"><b>@' + esc(p.ig || \"sin usuario\") + \"</b>\" +\n      (total === null ? '<span class=\"falta\">Sin precio</span>' : '<span class=\"num\">' + pesos(total) + \"</span>\") + \"</span>\" +\n      '<span class=\"det\">' + esc(p.modelo || \"Sin modelo\") + \" · \" + relativo(p.receivedAt) + \"</span></button>\";\n  }\n\n  function abrirPedido(clave) {\n    const p = (S.pedidos || []).find((x) => x.clave === clave);\n    if (!p) return;\n    const cancelado = p.estado === \"cancelado\";\n    const idx = ESTADOS.indexOf(p.estado);\n    const piezas = {};\n    ((p.diseno && p.diseno.piezas) || []).forEach((x) => { piezas[x.nombre] = (piezas[x.nombre] || 0) + 1; });\n    const nPiezas = Object.values(piezas).reduce((a, b) => a + b, 0);\n    const fila = (k, v) => v ? \"<div><dt>\" + k + \"</dt><dd>\" + v + \"</dd></div>\" : \"\";\n    const fecha = p.receivedAt ? new Date(p.receivedAt).toLocaleString(\"es-MX\", { weekday: \"long\", day: \"numeric\", month: \"long\", hour: \"numeric\", minute: \"2-digit\" }) : \"\";\n    const calculado = typeof p.total === \"number\";\n\n    const cuerpo =\n      '<div class=\"lamina foto-grande\">' + laminaPedido(p, true) + \"</div>\" +\n      '<div class=\"folio\"><b class=\"num\">' + esc(p.orderId || \"Sin folio\") + \"</b><span>\" + esc(fecha) + \"</span></div>\" +\n      (p.ig ? '<a class=\"ig\" href=\"https://instagram.com/' + encodeURIComponent(p.ig) + '\" target=\"_blank\" rel=\"noopener\">' + icono(\"ig\") + \"@\" + esc(p.ig) + (p.nombre ? \" · \" + esc(p.nombre) : \"\") + \"</a>\" : \"\") +\n      '<p class=\"bloque-t\">Estado</p>' +\n      '<div class=\"pasos\" role=\"group\" aria-label=\"Estado del pedido\"><span class=\"avance\" style=\"transform:scaleX(' + (cancelado || idx < 1 ? 0 : idx / 3) + ')\"></span>' +\n      ESTADOS.map((e, i) => {\n        const cls = cancelado ? \"\" : i < idx ? \" hecho\" : i === idx ? \" actual\" : \"\";\n        return '<button class=\"paso' + cls + '\" data-estado=\"' + e + '\" aria-pressed=\"' + (p.estado === e) + '\"><i>' + (cls === \" hecho\" ? icono(\"ok\") : \"\") + \"</i>\" + NOMBRE_ESTADO[e] + \"</button>\";\n      }).join(\"\") + \"</div>\" +\n      '<div class=\"cancelar-fila\">' + (cancelado\n        ? '<button class=\"btn btn-quiet btn-sm\" data-estado=\"nuevo\">Este pedido está cancelado · Reactivar</button>'\n        : '<button class=\"btn btn-quiet btn-sm\" data-estado=\"cancelado\">Cancelar pedido</button>') + \"</div>\" +\n      '<p class=\"bloque-t\">Precio</p>' +\n      (calculado\n        ? '<div class=\"dinero\"><span class=\"calculado num\">' + pesos(p.total) + \"</span><small>Calculado por la página<br>con el catálogo de ese día.</small></div>\"\n        : '<div class=\"dinero\"><div class=\"monto\"><label class=\"sr\" for=\"p-total\">Lo que cobraste</label><input class=\"in num\" id=\"p-total\" type=\"number\" min=\"0\" step=\"1\" inputmode=\"decimal\" placeholder=\"0\" value=\"' + (p.totalManual ?? \"\") + '\"></div>' +\n          \"<small>Lo que cobraste por este pedido.<br>Así cuenta en tus ingresos.</small></div>\") +\n      '<p class=\"bloque-t\">Detalle</p><dl class=\"ficha\">' +\n        fila(\"Tipo\", p.tipo === \"charms\" ? \"Funda con charms\" : \"Funda bedazzled\") +\n        fila(\"Modelo\", esc(p.modelo)) +\n        fila(\"Funda\", esc(p.funda)) +\n        fila(\"Pasta\", esc(p.pasta)) +\n        (p.tipo !== \"charms\" ? fila(\"Estilo\", esc(p.style)) + fila(\"Densidad\", esc(p.dens)) : \"\") +\n        fila(\"Priorizar\", p.prio && p.prio !== \"Ninguna\" ? esc(p.prio) : \"\") +\n        fila(\"Evitar\", p.excl && p.excl !== \"Ninguna\" ? esc(p.excl) : \"\") +\n        (nPiezas ? fila(\"Charms · \" + nPiezas, '<ul class=\"piezas\">' + Object.entries(piezas).sort((a, b) => b[1] - a[1])\n          .map(([n, c]) => \"<li>\" + esc(n) + '<span class=\"num\">× ' + c + \"</span></li>\").join(\"\") + \"</ul>\") : \"\") +\n      \"</dl>\" +\n      '<div class=\"campo\"><label for=\"p-nota\">Nota del taller</label><textarea class=\"in\" id=\"p-nota\" maxlength=\"500\" placeholder=\"Ej. envío a Zapopan, paga al entregar…\">' + esc(p.nota || \"\") + \"</textarea></div>\";\n\n    abrirHoja(\"Pedido\", cuerpo, '<button class=\"btn btn-ink\" id=\"p-guardar\">Guardar precio y nota</button>');\n\n    $$(\"#hoja-cuerpo [data-estado]\").forEach((b) => b.addEventListener(\"click\", () => cambiarEstado(p, b.dataset.estado)));\n    $(\"#p-guardar\").addEventListener(\"click\", async (e) => {\n      const btn = e.currentTarget, cambios = { clave: p.clave, nota: $(\"#p-nota\").value };\n      if ($(\"#p-total\")) cambios.totalManual = $(\"#p-total\").value;\n      btn.classList.add(\"ocupado\");\n      try {\n        const d = await api(\"/admin/pedidos\", { method: \"PUT\", json: cambios });\n        Object.assign(p, d.pedido);\n        hoja.close(); avisar(\"Pedido guardado.\");\n        refrescarLibro();\n      } catch (x) { btn.classList.remove(\"ocupado\"); }\n    });\n  }\n\n  async function cambiarEstado(p, estado) {\n    const antes = p.estado;\n    if (estado === antes) return;\n    const scroll = $(\"#hoja-cuerpo\").scrollTop;\n    const repintar = () => { abrirPedido(p.clave); $(\"#hoja-cuerpo\").scrollTop = scroll; pintarPedidos(); };\n    p.estado = estado; repintar();\n    try {\n      await api(\"/admin/pedidos\", { method: \"PUT\", json: { clave: p.clave, estado } });\n      avisar(estado === \"cancelado\" ? \"Pedido cancelado.\" : antes === \"cancelado\" ? \"Pedido reactivado.\" : \"Marcado como \" + NOMBRE_ESTADO[estado].toLowerCase() + \".\");\n      if (estado === \"cancelado\" || antes === \"cancelado\") refrescarLibro();\n    } catch (x) { p.estado = antes; repintar(); }\n  }\n\n  async function refrescarLibro() {\n    try {\n      S.rend = await api(\"/admin/rendimiento?\" + rangoMes());\n      if ($(\"#mesa\")) pintarPedidos();\n    } catch (e) { /* el libro se queda como estaba */ }\n  }\n\n  /* =================== GASTOS =================== */\n  function vistaGastos() {\n    $(\"#vista\").innerHTML =\n      '<div class=\"cabeza\"><h1>Gastos</h1>' + selectorMes() + \"</div>\" +\n      '<div class=\"dos\"><form class=\"alta\" id=\"g-form\" novalidate><h2>Anotar un gasto</h2>' +\n        '<div class=\"campo\"><label for=\"g-monto\">¿Cuánto?</label><div class=\"monto\"><input class=\"in num\" id=\"g-monto\" type=\"number\" min=\"0\" step=\"0.01\" inputmode=\"decimal\" placeholder=\"0\"></div></div>' +\n        '<div class=\"campo\"><label for=\"g-concepto\">¿En qué?</label><input class=\"in\" id=\"g-concepto\" maxlength=\"80\" placeholder=\"Gemas AB de 6 mm\"></div>' +\n        '<div class=\"campo\"><span class=\"lbl\" id=\"g-cat-l\">Categoría</span><div class=\"cats\" role=\"group\" aria-labelledby=\"g-cat-l\">' +\n          CATEGORIAS_GASTO.map((c) => '<button type=\"button\" class=\"chip\" data-cat=\"' + c + '\" aria-pressed=\"' + (S.catGasto === c) + '\">' + c + \"</button>\").join(\"\") + \"</div></div>\" +\n        '<div class=\"campo\"><label for=\"g-fecha\">Fecha</label><input class=\"in\" id=\"g-fecha\" type=\"date\" value=\"' + hoyIso() + '\" max=\"' + hoyIso() + '\"></div>' +\n        '<button class=\"btn btn-ink btn-full\" id=\"g-add\" type=\"submit\">' + icono(\"mas\") + \"Anotar gasto</button></form>\" +\n      '<div id=\"g-lista\"><div class=\"cargando\" style=\"grid-template-columns:1fr\"><i style=\"aspect-ratio:auto;height:220px\"></i></div></div></div>';\n    engancharMes(vistaGastos);\n    $$(\"[data-cat]\").forEach((b) => b.addEventListener(\"click\", () => {\n      S.catGasto = b.dataset.cat; $$(\"[data-cat]\").forEach((x) => x.setAttribute(\"aria-pressed\", String(x === b)));\n    }));\n    $(\"#g-form\").addEventListener(\"submit\", async (e) => {\n      e.preventDefault();\n      const monto = $(\"#g-monto\").value;\n      if (!monto || Number(monto) <= 0) { avisar(\"Escribe cuánto gastaste.\", true); $(\"#g-monto\").focus(); return; }\n      const btn = $(\"#g-add\"); btn.classList.add(\"ocupado\");\n      try {\n        const fecha = $(\"#g-fecha\").value;\n        await api(\"/admin/gastos\", { method: \"POST\", json: { monto, concepto: $(\"#g-concepto\").value, categoria: S.catGasto, fecha } });\n        $(\"#g-monto\").value = \"\"; $(\"#g-concepto\").value = \"\";\n        S.gastos = null; S.rend = null;\n        avisar(\"Gasto anotado.\" + (fecha && !fecha.startsWith(S.mes) ? \" Quedó en \" + nombreMes(fecha.slice(0, 7)) + \".\" : \"\"));\n        await cargarGastos(); $(\"#g-monto\").focus();\n      } catch (x) { /* avisado */ } finally { btn.classList.remove(\"ocupado\"); }\n    });\n    cargarGastos();\n  }\n\n  async function cargarGastos() {\n    try {\n      if (!S.gastos) S.gastos = (await api(\"/admin/gastos\")).gastos;\n    } catch (e) {\n      if (e.message !== \"sesion\" && $(\"#g-lista\")) $(\"#g-lista\").innerHTML = vacio(\"alerta\", \"No se pudieron cargar los gastos\", \"Revisa tu conexión e intenta de nuevo.\");\n      return;\n    }\n    const cont = $(\"#g-lista\");\n    if (!cont) return;\n    const delMes = S.gastos.filter((g) => String(g.fecha).startsWith(S.mes));\n    if (!delMes.length) {\n      cont.innerHTML = vacio(\"gastos\", \"Sin gastos en \" + nombreMes(S.mes), \"Anota cada compra del taller: material, envíos, empaque. Así sabes cuánto te queda de verdad.\");\n      return;\n    }\n    const total = delMes.reduce((a, g) => a + (g.monto || 0), 0);\n    const porCat = {}, porDia = {};\n    delMes.forEach((g) => {\n      porCat[g.categoria] = (porCat[g.categoria] || 0) + (g.monto || 0);\n      (porDia[g.fecha] = porDia[g.fecha] || []).push(g);\n    });\n    const cats = Object.entries(porCat).sort((a, b) => b[1] - a[1]);\n\n    cont.innerHTML =\n      '<dl class=\"libro\" style=\"grid-template-columns:1fr;margin-bottom:28px\"><div><dt>Gastado en ' + nombreMes(S.mes) + '</dt><dd class=\"num\"><small>$</small>' +\n        total.toLocaleString(\"es-MX\", { maximumFractionDigits: 2 }) + \"</dd></div></dl>\" +\n      (cats.length > 1 ? '<div class=\"reparto\"><h3 class=\"bloque-t\">En qué se fue</h3>' + cats.map(([c, m]) =>\n        '<div class=\"barra\"><span>' + esc(c) + '</span><span class=\"riel\"><i style=\"width:' + Math.max(3, (m / cats[0][1]) * 100) + '%\"></i></span><span class=\"num\">' + pesos(m) + \"</span></div>\").join(\"\") + \"</div>\" : \"\") +\n      Object.keys(porDia).sort().reverse().map((dia) => {\n        const f = new Date(dia + \"T12:00:00\");\n        const suma = porDia[dia].reduce((a, g) => a + (g.monto || 0), 0);\n        return '<section class=\"dia\"><h4><span>' + f.toLocaleDateString(\"es-MX\", { weekday: \"long\", day: \"numeric\", month: \"long\" }) + '</span><span class=\"num\">' + pesos(suma) + \"</span></h4>\" +\n          porDia[dia].map((g) => '<div class=\"gasto\"><div style=\"min-width:0\"><b>' + esc(g.concepto) + \"</b><small>\" + esc(g.categoria) + '</small></div><span class=\"cifra num\">' + pesos(g.monto) +\n            '</span><button class=\"quitar\" data-quitar=\"' + esc(g.id) + '\" aria-label=\"Borrar gasto ' + esc(g.concepto) + '\">' + icono(\"x\") + \"</button></div>\").join(\"\") + \"</section>\";\n      }).join(\"\");\n\n    $$(\"[data-quitar]\", cont).forEach((b) => b.addEventListener(\"click\", async () => {\n      const g = S.gastos.find((x) => x.id === b.dataset.quitar);\n      if (!g || !confirm(\"¿Borrar “\" + g.concepto + \"” de \" + pesos(g.monto) + \"?\")) return;\n      try {\n        await api(\"/admin/gastos/\" + g.id, { method: \"DELETE\" });\n        S.gastos = S.gastos.filter((x) => x.id !== g.id); S.rend = null;\n        avisar(\"Gasto borrado.\"); cargarGastos();\n      } catch (x) { /* avisado */ }\n    }));\n  }\n\n  /* =================== CATALOGO =================== */\n  async function cargarCatalogo() {\n    if (!S.catalogo) {\n      const r = await fetch(\"/catalog\", { credentials: \"same-origin\" });\n      if (!r.ok) throw new Error(\"catalogo\");\n      S.catalogo = await r.json();\n    }\n  }\n\n  async function vistaCatalogo() {\n    const sub = [[\"charms\", \"Charms\"], [\"precios\", \"Precios\"], [\"stock\", \"Fundas en stock\"]];\n    $(\"#vista\").innerHTML = '<div class=\"cabeza\"><h1>Catálogo</h1></div>' +\n      '<div class=\"seg\" role=\"group\" aria-label=\"Parte del catálogo\">' + sub.map(([k, n]) => '<button data-sub=\"' + k + '\" aria-pressed=\"' + (S.subCat === k) + '\">' + n + \"</button>\").join(\"\") + \"</div>\" +\n      '<div id=\"cat\"><div class=\"cargando\">' + \"<i></i>\".repeat(4) + \"</div></div>\";\n    $$(\"[data-sub]\").forEach((b) => b.addEventListener(\"click\", () => {\n      S.subCat = b.dataset.sub; $$(\"[data-sub]\").forEach((x) => x.setAttribute(\"aria-pressed\", String(x === b))); pintarCatalogo();\n    }));\n    try {\n      await cargarCatalogo();\n      if (!S.charms || !S.precios) {\n        const [c, p] = await Promise.all([api(\"/admin/charms\"), api(\"/admin/precios\")]);\n        S.charms = c.charms; S.precios = p.precios;\n      }\n      if ($(\"#cat\")) pintarCatalogo();\n    } catch (e) {\n      if (e.message !== \"sesion\" && $(\"#cat\")) $(\"#cat\").innerHTML = vacio(\"alerta\", \"No se pudo cargar el catálogo\", \"Revisa tu conexión e intenta de nuevo.\");\n    }\n  }\n  const pintarCatalogo = () => ({ charms: pintarCharms, precios: pintarPrecios, stock: pintarStock })[S.subCat]();\n\n  function pintarCharms() {\n    const cont = $(\"#cat\");\n    const tiles = S.charms.map((c, i) => {\n      const oculto = c.activo === false;\n      const sello = oculto ? '<span class=\"sello e-cancelado\">Oculto</span>' : !c.stock ? '<span class=\"sello e-nuevo\">Agotado</span>' : \"\";\n      return '<article class=\"charm' + (oculto ? \" oculto\" : \"\") + '\" style=\"--i:' + Math.min(i, 20) + '\">' +\n        '<button class=\"lamina\" data-editar=\"' + esc(c.id) + '\" aria-label=\"Editar ' + esc(c.nombre) + '\">' +\n          (c.imgId ? '<img src=\"/img/' + esc(c.imgId) + '\" alt=\"\" loading=\"lazy\">' : icono(\"catalogo\")) + sello + \"</button>\" +\n        \"<h3>\" + esc(c.nombre) + \"</h3>\" +\n        '<div class=\"linea\"><span class=\"precio num\">' + (c.precio == null ? \"Sin precio\" : pesos(c.precio)) + \"</span>\" +\n          '<span class=\"stepper' + (!c.stock ? \" cero\" : \"\") + '\" data-id=\"' + esc(c.id) + '\"><button data-d=\"-1\" aria-label=\"Una pieza menos de ' + esc(c.nombre) + '\">' + icono(\"menos\") +\n          '</button><output class=\"num\" aria-label=\"Piezas en stock\">' + (c.stock || 0) + '</output><button data-d=\"1\" aria-label=\"Una pieza más de ' + esc(c.nombre) + '\">' + icono(\"mas\") + \"</button></span></div></article>\";\n    }).join(\"\");\n    cont.innerHTML = '<div class=\"vitrina\"><button class=\"nuevo\" data-nuevo>' + icono(\"mas\") + \"Nuevo charm</button>\" + tiles + \"</div>\" +\n      (S.charms.length ? \"\" : '<p class=\"nota\" style=\"margin-top:22px\">Todavía no hay charms en el catálogo. Agrega el primero con su foto, precio y piezas.</p>');\n    $(\"[data-nuevo]\", cont).addEventListener(\"click\", () => editarCharm(null));\n    $$(\"[data-editar]\", cont).forEach((b) => b.addEventListener(\"click\", () => editarCharm(b.dataset.editar)));\n    $$(\".stepper\", cont).forEach((st) => $$(\"button\", st).forEach((b) => b.addEventListener(\"click\", () => moverStock(st, Number(b.dataset.d)))));\n  }\n\n  const esperaStock = {};\n  function moverStock(st, d) {\n    const c = S.charms.find((x) => x.id === st.dataset.id);\n    if (!c) return;\n    c.stock = Math.max(0, (c.stock || 0) + d);\n    $(\"output\", st).textContent = c.stock;\n    st.classList.toggle(\"cero\", !c.stock);\n    // Varios toques seguidos se guardan como uno solo.\n    clearTimeout(esperaStock[c.id]);\n    esperaStock[c.id] = setTimeout(async () => {\n      try {\n        const r = await api(\"/admin/charms/\" + c.id, { method: \"PUT\", json: { stock: c.stock } });\n        Object.assign(c, r.charm);\n        const tile = st.closest(\".charm\"), sello = tile && $(\".lamina .sello\", tile);\n        if (tile && c.activo !== false) {\n          if (!c.stock && !sello) $(\".lamina\", tile).insertAdjacentHTML(\"beforeend\", '<span class=\"sello e-nuevo\">Agotado</span>');\n          if (c.stock && sello) sello.remove();\n        }\n      } catch (e) { /* avisado */ }\n    }, 650);\n  }\n\n  function editarCharm(id) {\n    const c = id ? S.charms.find((x) => x.id === id) : { nombre: \"\", categoria: \"\", precio: null, stock: 0, imgId: null, activo: true };\n    if (!c) return;\n    let imgId = c.imgId, activo = c.activo !== false, subiendo = null;\n    const cats = [...new Set(S.charms.map((x) => x.categoria).filter(Boolean))];\n    const zona = (src) => src\n      ? '<img src=\"' + esc(src) + '\" alt=\"\"><small>Toca para cambiar la foto</small>'\n      : icono(\"subir\") + \"Foto del charm<small>Toca o arrastra una imagen</small>\";\n    abrirHoja(id ? \"Editar charm\" : \"Nuevo charm\",\n      '<form class=\"forma\" id=\"c-form\" novalidate>' +\n        '<label class=\"soltar' + (imgId ? \" con-foto\" : \"\") + '\" id=\"c-soltar\"><span id=\"c-zona\" style=\"display:contents\">' + zona(imgId && \"/img/\" + imgId) + \"</span>\" +\n          '<input type=\"file\" id=\"c-img\" accept=\"image/*\" aria-label=\"Foto del charm\"></label>' +\n        '<div class=\"campo\"><label for=\"c-nombre\">Nombre</label><input class=\"in\" id=\"c-nombre\" maxlength=\"60\" value=\"' + esc(c.nombre) + '\" placeholder=\"Estrella de mar dorada\"></div>' +\n        '<div class=\"campo\"><label for=\"c-cat\">Categoría</label><input class=\"in\" id=\"c-cat\" maxlength=\"40\" list=\"c-cats\" value=\"' + esc(c.categoria) + '\" placeholder=\"Mar\"><datalist id=\"c-cats\">' +\n          cats.map((x) => \"<option>\" + esc(x) + \"</option>\").join(\"\") + \"</datalist></div>\" +\n        '<div class=\"fila2\"><div class=\"campo\"><label for=\"c-precio\">Precio</label><div class=\"monto\"><input class=\"in num\" id=\"c-precio\" type=\"number\" min=\"0\" step=\"1\" inputmode=\"decimal\" value=\"' + (c.precio ?? \"\") + '\" placeholder=\"—\"></div></div>' +\n          '<div class=\"campo\"><label for=\"c-stock\">Piezas</label><input class=\"in num\" id=\"c-stock\" type=\"number\" min=\"0\" step=\"1\" inputmode=\"numeric\" value=\"' + (c.stock || 0) + '\"></div></div>' +\n        '<div class=\"fila-interruptor\"><span>Visible en la página<small>Apágalo para esconderlo sin borrarlo.</small></span><button type=\"button\" class=\"interruptor\" role=\"switch\" id=\"c-activo\" aria-checked=\"' + activo + '\" aria-label=\"Visible en la página\"></button></div>' +\n      \"</form>\",\n      (id ? '<button class=\"btn btn-quiet btn-sm\" id=\"c-borrar\">Borrar</button>' : \"\") + '<button class=\"btn btn-ink\" id=\"c-guardar\">' + (id ? \"Guardar cambios\" : \"Agregar charm\") + \"</button>\");\n\n    $(\"#c-activo\").addEventListener(\"click\", (e) => { activo = !activo; e.currentTarget.setAttribute(\"aria-checked\", String(activo)); });\n    const soltar = $(\"#c-soltar\");\n    [\"dragenter\", \"dragover\"].forEach((ev) => soltar.addEventListener(ev, () => soltar.classList.add(\"encima\")));\n    [\"dragleave\", \"drop\"].forEach((ev) => soltar.addEventListener(ev, () => soltar.classList.remove(\"encima\")));\n    $(\"#c-img\").addEventListener(\"change\", (e) => {\n      const f = e.target.files[0]; if (!f) return;\n      soltar.classList.add(\"con-foto\");\n      $(\"#c-zona\").innerHTML = zona(URL.createObjectURL(f)).replace(\"Toca para cambiar la foto\", \"Subiendo…\");\n      subiendo = subirFoto(f, 900).then((nuevo) => {\n        imgId = nuevo;\n        const s = $(\"#c-zona small\"); if (s) s.textContent = \"Toca para cambiar la foto\";\n      }).catch(() => { const s = $(\"#c-zona small\"); if (s) s.textContent = \"No se subió. Toca para intentar otra vez\"; })\n        .finally(() => { subiendo = null; });\n    });\n    if (id) {\n      let seguro = false;\n      $(\"#c-borrar\").addEventListener(\"click\", async (e) => {\n        const btn = e.currentTarget;\n        if (!seguro) { seguro = true; btn.textContent = \"¿Borrar? Toca otra vez\"; btn.style.color = \"var(--maroon)\"; return; }\n        btn.classList.add(\"ocupado\");\n        try {\n          await api(\"/admin/charms/\" + id, { method: \"DELETE\" });\n          S.charms = S.charms.filter((x) => x.id !== id); hoja.close(); avisar(\"Charm borrado.\"); pintarCharms();\n        } catch (x) { btn.classList.remove(\"ocupado\"); }\n      });\n    }\n    $(\"#c-guardar\").addEventListener(\"click\", async (e) => {\n      const nombre = $(\"#c-nombre\").value.trim();\n      if (!nombre) { avisar(\"Ponle nombre al charm.\", true); $(\"#c-nombre\").focus(); return; }\n      const btn = e.currentTarget; btn.classList.add(\"ocupado\");\n      if (subiendo) await subiendo;\n      const datos = { nombre, categoria: $(\"#c-cat\").value, precio: $(\"#c-precio\").value, stock: $(\"#c-stock\").value, imgId, activo };\n      try {\n        const d = await api(id ? \"/admin/charms/\" + id : \"/admin/charms\", { method: id ? \"PUT\" : \"POST\", json: datos });\n        if (id) S.charms = S.charms.map((x) => x.id === id ? d.charm : x); else S.charms.unshift(d.charm);\n        hoja.close(); avisar(id ? \"Charm guardado.\" : \"Charm agregado.\"); pintarCharms();\n      } catch (x) { btn.classList.remove(\"ocupado\"); }\n    });\n  }\n\n  function pintarPrecios() {\n    const P = S.precios || {};\n    let n = 0;\n    const renglon = (attr, k, etiqueta, v) => {\n      const idc = \"pr-\" + (n++);\n      return '<div class=\"renglon\"><label for=\"' + idc + '\">' + esc(etiqueta) + '</label><span class=\"puntos\"></span><div class=\"monto\"><input class=\"in num\" id=\"' + idc + '\" ' + attr + '=\"' + esc(k) +\n        '\" type=\"number\" min=\"0\" step=\"1\" inputmode=\"decimal\" value=\"' + (v ?? \"\") + '\" placeholder=\"—\"></div></div>';\n    };\n    $(\"#cat\").innerHTML = '<form class=\"tarifa\" id=\"pr-form\" novalidate>' +\n      '<p class=\"nota\">Mientras falte un precio, la página dice “precio a confirmar” en vez de inventar un número.</p>' +\n      '<section><h3 class=\"bloque-t\">Precio base por estilo</h3>' + (S.catalogo.estilos || []).map((e) => renglon(\"data-base\", e, e, (P.base || {})[e])).join(\"\") + \"</section>\" +\n      '<section><h3 class=\"bloque-t\">Extra por densidad</h3>' + (S.catalogo.densidades || []).map((d) => renglon(\"data-dens\", d, d, (P.densidad || {})[d])).join(\"\") + \"</section>\" +\n      '<section><h3 class=\"bloque-t\">Envío</h3>' + renglon(\"data-envio\", \"envio\", \"Envío · 0 es gratis\", P.envio) + \"</section>\" +\n      '<div class=\"guardar-fijo\"><button class=\"btn btn-ink\" id=\"pr-guardar\" type=\"submit\">Guardar precios</button></div></form>';\n    $(\"#pr-form\").addEventListener(\"submit\", async (e) => {\n      e.preventDefault();\n      const base = {}, densidad = {};\n      $$(\"[data-base]\").forEach((i) => { base[i.dataset.base] = i.value; });\n      $$(\"[data-dens]\").forEach((i) => { densidad[i.dataset.dens] = i.value; });\n      const btn = $(\"#pr-guardar\"); btn.classList.add(\"ocupado\");\n      try {\n        const d = await api(\"/admin/precios\", { method: \"PUT\", json: { base, densidad, envio: $(\"[data-envio]\").value } });\n        S.precios = d.precios; avisar(\"Precios guardados.\");\n      } catch (x) { /* avisado */ } finally { btn.classList.remove(\"ocupado\"); }\n    });\n  }\n\n  function pintarStock() {\n    const estilos = S.catalogo.estilos || [];\n    if (!S.estiloStock || !estilos.includes(S.estiloStock)) S.estiloStock = estilos[0];\n    const actual = (S.catalogo.stock || {})[S.estiloStock] || {};\n    const etiqueta = (v) => v === undefined || v === null ? [\"Sin límite\", \"\"] : v === 0 ? [\"Agotado\", \"agotado\"] : [v + (v === 1 ? \" pieza\" : \" piezas\"), \"\"];\n    $(\"#cat\").innerHTML =\n      '<div class=\"filtros\" role=\"group\" aria-label=\"Estilo de funda\">' + estilos.map((e) => '<button class=\"chip\" data-estilo=\"' + esc(e) + '\" aria-pressed=\"' + (e === S.estiloStock) + '\">' + esc(e) + \"</button>\").join(\"\") + \"</div>\" +\n      '<p class=\"nota\">Déjalo vacío si hay de sobra. Pon <b>0</b> cuando se acabe una funda: deja de ofrecerse en la página hasta que la vuelvas a subir.</p>' +\n      '<div class=\"modelos\">' + MODELOS.map((m) => {\n        const [txt, cls] = etiqueta(actual[m]);\n        return '<div class=\"modelo\"><b>' + esc(m) + '</b><span class=\"estado ' + cls + '\">' + txt + '</span><input class=\"in num\" type=\"number\" min=\"0\" step=\"1\" inputmode=\"numeric\" aria-label=\"Piezas de ' +\n          esc(m) + '\" data-modelo=\"' + esc(m) + '\" value=\"' + (actual[m] ?? \"\") + '\" placeholder=\"—\"></div>';\n      }).join(\"\") + \"</div>\";\n    $$(\"[data-estilo]\").forEach((b) => b.addEventListener(\"click\", () => { S.estiloStock = b.dataset.estilo; pintarStock(); }));\n    $$(\"[data-modelo]\").forEach((inp) => inp.addEventListener(\"change\", async () => {\n      const modelo = inp.dataset.modelo;\n      try {\n        const d = await api(\"/admin/stock\", { method: \"PUT\", json: { estilo: S.estiloStock, modelo, cantidad: inp.value } });\n        S.catalogo.stock = d.stock;\n        const [txt, cls] = etiqueta((d.stock[S.estiloStock] || {})[modelo]);\n        const e = inp.parentElement.querySelector(\".estado\"); e.textContent = txt; e.className = \"estado \" + cls;\n        avisar(modelo + \": \" + txt.toLowerCase() + \".\");\n      } catch (x) { /* avisado */ }\n    }));\n  }\n\n  /* =================== FOTOS =================== */\n  async function vistaFotos() {\n    $(\"#vista\").innerHTML = '<div class=\"cabeza\"><h1>Fotos</h1></div><div id=\"fotos\"><div class=\"cargando\">' + \"<i></i>\".repeat(4) + \"</div></div>\";\n    try { await cargarCatalogo(); if ($(\"#fotos\")) pintarFotos(); }\n    catch (e) { if ($(\"#fotos\")) $(\"#fotos\").innerHTML = vacio(\"alerta\", \"No se pudieron cargar las fotos\", \"Revisa tu conexión e intenta de nuevo.\"); }\n  }\n\n  const NOMBRE_SECCION = (s) => s.charAt(0).toUpperCase() + s.slice(1).replace(/[-_]/g, \" \");\n  function pintarFotos() {\n    const fotos = S.catalogo.fotos || {};\n    const secciones = Object.keys(fotos);\n    if (!S.seccionFoto || !secciones.includes(S.seccionFoto)) S.seccionFoto = secciones[0];\n    const lista = fotos[S.seccionFoto] || [];\n    $(\"#fotos\").innerHTML =\n      '<div class=\"seg\" role=\"group\" aria-label=\"Sección de la página\">' + secciones.map((s) => '<button data-sec=\"' + esc(s) + '\" aria-pressed=\"' + (s === S.seccionFoto) + '\">' + esc(NOMBRE_SECCION(s)) + \"</button>\").join(\"\") + \"</div>\" +\n      '<p class=\"nota\">' + (lista.length ? \"Se muestran en este orden en la página.\" : \"Esta sección todavía no tiene fotos propias: la página usa las de siempre.\") + \"</p>\" +\n      '<div class=\"galeria\"><label class=\"soltar\" id=\"f-soltar\">' + icono(\"subir\") + \"Subir fotos<small>Varias a la vez · se comprimen solas</small>\" +\n        '<input type=\"file\" id=\"f-file\" accept=\"image/*\" multiple aria-label=\"Subir fotos\"></label>' +\n        lista.map((id, i) => '<figure class=\"foto\" style=\"animation-delay:' + Math.min(i, 20) * 30 + 'ms\"><img src=\"/img/' + esc(id) + '\" alt=\"\" loading=\"lazy\"><span class=\"orden num\">' + (i + 1) +\n          '</span><button class=\"quitar\" data-quitar-foto=\"' + esc(id) + '\" aria-label=\"Quitar foto ' + (i + 1) + '\">' + icono(\"x\") + \"</button></figure>\").join(\"\") + \"</div>\";\n    $$(\"[data-sec]\").forEach((b) => b.addEventListener(\"click\", () => { S.seccionFoto = b.dataset.sec; pintarFotos(); }));\n    const soltar = $(\"#f-soltar\");\n    [\"dragenter\", \"dragover\"].forEach((ev) => soltar.addEventListener(ev, () => soltar.classList.add(\"encima\")));\n    [\"dragleave\", \"drop\"].forEach((ev) => soltar.addEventListener(ev, () => soltar.classList.remove(\"encima\")));\n    $(\"#f-file\").addEventListener(\"change\", async (e) => {\n      const files = Array.from(e.target.files); if (!files.length) return;\n      const sec = S.seccionFoto;\n      avisar(\"Subiendo \" + files.length + (files.length === 1 ? \" foto…\" : \" fotos…\"));\n      const ids = [];\n      let fallos = 0;\n      for (const f of files) { try { ids.push(await subirFoto(f, 1600)); } catch (x) { fallos++; } }\n      if (!ids.length) { avisar(fallos === 1 ? \"La foto no se pudo subir.\" : \"No se pudo subir ninguna foto.\", true); return; }\n      try {\n        const d = await api(\"/admin/fotos/\" + sec, { method: \"PUT\", json: { fotos: (S.catalogo.fotos[sec] || []).concat(ids) } });\n        S.catalogo.fotos[sec] = d.fotos;\n        avisar((ids.length === 1 ? \"Foto agregada.\" : ids.length + \" fotos agregadas.\") + (fallos ? \" \" + fallos + \" no se pudo subir.\" : \"\"), !!fallos);\n        pintarFotos();\n      } catch (x) { /* avisado */ }\n    });\n    $$(\"[data-quitar-foto]\").forEach((b) => b.addEventListener(\"click\", async () => {\n      const sec = S.seccionFoto;\n      try {\n        const d = await api(\"/admin/fotos/\" + sec, { method: \"PUT\", json: { fotos: (S.catalogo.fotos[sec] || []).filter((x) => x !== b.dataset.quitarFoto) } });\n        S.catalogo.fotos[sec] = d.fotos; avisar(\"Foto quitada.\"); pintarFotos();\n      } catch (x) { /* avisado */ }\n    }));\n  }\n\n  /* ---------- fotos: se reducen en el navegador antes de subir ---------- */\n  function comprimir(file, maxLado) {\n    return new Promise((ok, mal) => {\n      const img = new Image();\n      img.onload = () => {\n        const k = Math.min(1, maxLado / Math.max(img.width, img.height));\n        const c = document.createElement(\"canvas\");\n        c.width = Math.round(img.width * k); c.height = Math.round(img.height * k);\n        c.getContext(\"2d\").drawImage(img, 0, 0, c.width, c.height);\n        URL.revokeObjectURL(img.src);\n        c.toBlob((b) => {\n          if (b && b.type === \"image/webp\") return ok(b);\n          // Safari no codifica webp: PNG si puede traer transparencia (charms recortados), si no JPEG.\n          const png = /png|webp/.test(file.type);\n          c.toBlob((j) => j ? ok(j) : mal(new Error(\"canvas\")), png ? \"image/png\" : \"image/jpeg\", 0.88);\n        }, \"image/webp\", 0.86);\n      };\n      img.onerror = () => mal(new Error(\"no_es_imagen\"));\n      img.src = URL.createObjectURL(file);\n    });\n  }\n  async function subirFoto(file, maxLado) {\n    const blob = await comprimir(file, maxLado);\n    const d = await api(\"/admin/imagen\", { method: \"POST\", tipo: blob.type, body: blob });\n    return d.id;\n  }\n\n  /* ---------- arranque ---------- */\n  function arrancar(usuario) {\n    S.usuario = usuario;\n    $$(\"[data-usuario]\").forEach((e) => { e.textContent = usuario === \"script\" ? \"\" : usuario; });\n    $(\"#login\").hidden = true;\n    $(\"#app\").hidden = false;\n    ir();\n    // El contador de nuevos se llena aunque se entre directo a otra seccion.\n    if (!S.pedidos && location.hash && location.hash !== \"#pedidos\") api(\"/admin/pedidos?mes=\" + S.mes).then((d) => { if (!S.pedidos) S.pedidos = d.pedidos; actualizarCuenta(); }).catch(() => {});\n  }\n  fetch(\"/admin/yo\", { credentials: \"same-origin\" })\n    .then((r) => r.ok ? r.json() : Promise.reject(r.status))\n    .then((d) => arrancar(d.usuario))\n    .catch(mostrarLogin);\n})();\n</script>\n</body>\n</html>\n";
